const r = $('Process product entry one at a time').all();

const CATEGORY_MAP = {
  "PCs": 17,
  "Accessories": 18,
  "New Arrivals": 36,
};

let returnArray = [];

for(let item of r){
  const specs = JSON.parse(item.json.specs_json || '[]');
  item.json.specs_json = specs.map((s, i) => ({
    name: s.key, position: i, visible: true,
    variation: false, options: [s.value],
  }));

  let category_id = item.json.category_ids == "PCs" ? 17 : item.json.category_ids == "Accessories" ? 18 : item.json.category_ids == "New Arrivals" ? 1 : 1;

  returnArray.push({ json: {
  name: item.json.name,
  sku: item.json.sku,
    composite_key: item.json.composite_key,
  source_id: item.json.source_id,
  type: 'simple',
  status: 'draft',
  catalog_visibility: 'visible',
  regular_price: String(item.json.regular_price),
  srp: item.json.srp,
  short_description: item.json.short_description || '',
  description: item.json.description || '',
  manage_stock: item.json.stock_qty !== '' && item.json.stock_qty !== null,
  stock_quantity: Number(item.json.stock_qty) || 0,
  categories: [{ id: category_id }],
  attributes: specs.map((s, i) => ({
    name: s.key, position: i, visible: true,
    variation: false, options: [ s.key === "Weight (kg)" ? s.value.toString() : s.key === "Dimensions (WxHxD)" ? s.value : s.value.toString()]
  })),
  meta_data: [
    { key: '_supplier_cost',  value: String(item.json.supplier_price) },
    { key: '_source_file',    value: item.json.source_file },
    { key: '_run_id',         value: item.json.run_id },
  ]
}});


}
return returnArray;
