const TOL_DOWN = 0.15;   // drops are suspicious
const TOL_UP   = 0.40;   // increases are normal business
const MIN_PESO = 100;    // ignore noise on cheap items

const row = $('Process product entry one at a time').first().json;
let price = 0;
if($input.first().json.regular_price){
  price = parseInt($input.first().json.regular_price)
}else{
  price = $input.first().json.srp
}
const existing = parseFloat($('fetch given SKU').first().json.body[0].price || 0);
const incoming = price;

const delta    = incoming - existing;
const variance = existing > 0 ? Math.abs(delta) / existing : 0;
const dir      = delta < 0 ? 'down' : 'up';
const limit    = dir === 'down' ? TOL_DOWN : TOL_UP;

const blocked  = variance > limit && Math.abs(delta) > MIN_PESO;

return [{ json: {
  ...row,
  woo_id: $input.first().json.id,
  existing_price: existing,
  variance_pct: Math.round(variance * 1000) / 10,
  direction: dir,
  blocked,
  notes: blocked
    ? `price ${dir} ${Math.round(variance*100)}%: ${existing} → ${incoming}`
    : row.notes,
}}];

